```python
def transform(grid):
    h = len(grid)
    w = len(grid[0])
    sep = None
    for c in range(w):
        col = {grid[r][c] for r in range(h)}
        if len(col) == 1:
            v = col.pop()
            others = {grid[r][cc] for r in range(h) for cc in range(w) if cc != c}
            if v not in others:
                sep = ('c', c)
                break
    if sep is None:
        for r in range(h):
            row = set(grid[r])
            if len(row) == 1:
                v = row.pop()
                others = {grid[rr][cc] for rr in range(h) if rr != r for cc in range(w)}
                if v not in others:
                    sep = ('r', r)
                    break
    if sep is None:
        return grid
    if sep[0] == 'c':
        c = sep[1]
        A = [row[:c] for row in grid]
        B = [row[c + 1:] for row in grid]
        n, m = h, min(c, w - c - 1)
    else:
        r = sep[1]
        A = grid[:r]
        B = grid[r + 1:]
        n, m = min(r, h - r - 1), w
    setA = {v for row in A for v in row}
    setB = {v for row in B for v in row}
    common = setA & setB
    accent = sorted(common)[0] if common else 0
    out = []
    for i in range(n):
        out.append([3 if (A[i][j] == accent and B[i][j] == accent) else accent
                    for j in range(m)])
    return out
